/**
 * Monday.com Node - Version 2
 * Discriminator: resource=board, operation=duplicateBoard
 */


interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Create a copy of a board: structure only, or including items and updates */
export type MondayComV2BoardDuplicateBoardParams = {
  resource: 'board';
  operation: 'duplicateBoard';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * How much of the board to copy
 * @default duplicate_board_with_structure
 */
    duplicateType?: 'duplicate_board_with_pulses' | 'duplicate_board_with_structure' | 'duplicate_board_with_pulses_and_updates' | Expression<string>;
/**
 * Options
 * @default {}
 */
    duplicateBoardOptions?: {
    /** The name of the new board; left unset, monday derives one from the original
     */
    boardName?: string | Expression<string>;
    /** The folder to create the duplicate in. Select a workspace first — the list shows that workspace’s folders. Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getWorkspaceFolders
     */
    folderId?: string | Expression<string>;
    /** Whether to copy the original board’s subscribers to the new board
     * @default false
     */
    keepSubscribers?: boolean | Expression<boolean>;
    /** The workspace to create the duplicate in; left unset, it stays in the original board’s workspace. Picking a workspace here also loads its folders into the Folder option.
     * @searchListMethod searchWorkspaces
     * @default {"mode":"list","value":""}
     */
    workspaceId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
  };
/**
 * The board to operate on
 * @searchListMethod searchBoards
 * @default {"mode":"list","value":""}
 */
    boardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
};

export type MondayComV2BoardDuplicateBoardNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2BoardDuplicateBoardParams> & { credentials?: Credentials };
};